create policy "seller_logos_read" on storage.objects for select using (bucket_id = 'seller-logos');
create policy "seller_logos_owner_insert" on storage.objects for insert to authenticated with check (bucket_id = 'seller-logos' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "seller_logos_owner_update" on storage.objects for update to authenticated using (bucket_id = 'seller-logos' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "seller_logos_owner_delete" on storage.objects for delete to authenticated using (bucket_id = 'seller-logos' and (storage.foldername(name))[1] = auth.uid()::text);